#include "vwap.hpp"
#include <cmath>
#include <iostream>
#include <stdexcept>
static void check(bool b,const char* s){if(!b)throw std::runtime_error(s);}static void near(double a,double b){check(std::isfinite(a)&&std::abs(a-b)<1e-10,"formula mismatch");}template<class F>void refuses(F f){bool bad=false;try{f();}catch(...){bad=true;}check(bad,"expected refusal");}
static vwap::Point point(long long time,std::string day,double close,double volume,double amount=vwap::missing()){vwap::Point p;p.time=time;p.session=day;p.close=close;p.high=close+2;p.low=close-1;p.volume=volume;p.amount=amount;return p;}
int main(){try{vwap::Params p;p.volumeUnit="lots";std::vector<vwap::Point> rows{point(1,"2000-01-01",10,1),point(2,"2000-01-01",20,3)};auto old=vwap::calculate(rows,p);near(old.values[0],10);near(old.values[1],17.5);check(old.approximate&&old.label.find("收盘价")!=std::string::npos,"legacy approximation explicit");p.mode="hlc3-approx";auto hlc=vwap::calculate(rows,p);near(hlc.values[1],17.5+1.0/3);p.mode="actual-amount";p.volumeToShares=100;p.amountToCny=10000;p.priceBasis="unadjusted";rows[0].amount=.1;rows[1].amount=.6;auto actual=vwap::calculate(rows,p);near(actual.values[1],17.5);check(!actual.approximate,"actual mode explicit");auto unknown=p;unknown.volumeToShares=vwap::missing();check(!std::isfinite(vwap::calculate(rows,unknown).values[0]),"no guessed lot scale");unknown=p;unknown.priceBasis="adjusted";check(!std::isfinite(vwap::calculate(rows,unknown).values[0]),"no unadjusted amount vs qfq price");auto missing=rows;missing[0].amount=vwap::missing();auto gap=vwap::calculate(missing,p);check(!std::isfinite(gap.values[0])&&!std::isfinite(gap.values[1]),"missing amount never approximate fallback or skip");rows.push_back(point(3,"2000-01-02",30,2,.6));actual=vwap::calculate(rows,p);near(actual.values[2],30);check(actual.breakBefore[2],"new day reset/segment");auto prefix=vwap::calculate({rows[0],rows[1]},p);near(prefix.values[0],actual.values[0]);near(prefix.values[1],actual.values[1]);auto future=rows;future.push_back(point(4,"2000-01-02",1000,100,1000));auto extended=vwap::calculate(future,p);for(int i=0;i<3;i++)near(extended.values[i],actual.values[i]);auto lunch=rows[0];lunch.time=2;lunch.axisGap=true;auto after=rows[1];after.time=3;auto noon=vwap::calculate({rows[0],lunch,after},p);check(!std::isfinite(noon.values[1])&&noon.breakBefore[2],"axis gap kept not joined");near(noon.values[2],17.5);p.quantities="cumulative";auto cumulative=vwap::calculate({point(1,"2000-01-01",10,1,.1),point(2,"2000-01-01",15,4,.7)},p);near(cumulative.values[1],17.5);auto recovering=vwap::calculate({point(1,"2000-01-01",10,1,vwap::missing()),point(2,"2000-01-01",15,4,.7)},p);check(!std::isfinite(recovering.values[0]),"missing past remains missing");near(recovering.values[1],17.5);auto reset=vwap::calculate({point(1,"2000-01-01",10,4,.7),point(2,"2000-01-01",10,1,.1),point(3,"2000-01-01",10,8,1.4)},p);check(!std::isfinite(reset.values[1])&&!std::isfinite(reset.values[2]),"in-day counter reset cannot resume blindly");p.quantities="incremental";p.period="week";refuses([&]{vwap::calculate(rows,p);});p.anchor="loaded-window";refuses([&]{vwap::calculate(rows,p);});p.anchorId="actual-loaded-fixture-start";auto window=vwap::calculate(rows,p);near(window.values[2],(1000+6000+6000)/600.0);check(window.label.find("加载窗口")!=std::string::npos,"explicit cross-day window not session claim");p.mode="legacy-close-approx";p.period="intraday";p.anchor="session";auto zero=vwap::calculate({point(1,"2000-01-01",10,0),point(2,"2000-01-01",10,1),point(3,"2000-01-01",20,0)},p);check(!std::isfinite(zero.values[0]),"zero denominator missing");near(zero.values[2],10);std::cout<<"PASS VWAP old-close/HLC3/actual scale/no-fallback/session/window/cumulative/gap/axis/null/causal/unadjusted tests; pure staging only\n";return 0;}catch(const std::exception&e){std::cerr<<e.what()<<'\n';return 1;}}
